import { writeFileSync } from 'node:fs';
import { questions } from '../src/data/questions.js';

const rows = questions.map(
  (question) => `(${question.id}, '${JSON.stringify(question).replaceAll("'", "''")}'::jsonb)`,
);
writeFileSync(
  new URL('../supabase/migrations/0002_builtin_questions.sql', import.meta.url),
  '-- Generated by npm run db:seed:generate. Keep in sync with src/data/questions.js.\n' +
    'insert into public.builtin_questions(id,payload) values\n' +
    rows.join(',\n') +
    ';\n',
);
console.log('Generated seed for ' + rows.length + ' source questions.');
